def check_win(board: np.ndarray) -> tuple[bool, int]:
    """Checks if the current player has won. Returns (True, 1) or (False, -1)."""
    win_patterns = [
        [0, 1, 2], [3, 4, 5], [6, 7, 8],
        [0, 3, 6], [1, 4, 7], [2, 5, 8],
        [0, 4, 8], [2, 4, 6]
    ]
    player = board[0]  # Assumes X always starts and fills first
    for pattern in win_patterns:
        if all(board[i] == player for i in pattern):
            return True, player
    return False, 0

def check_draw(board: np.ndarray) -> bool:
    """Checks if the game is a draw (all cells filled). Returns True if so."""
    return all(cell != EMPTY_CELL for cell in board)

def check_win(board: np.ndarray) -> tuple[bool, int]:
    """Checks if the current player has won. Returns (True, 1) or (False, -1)."""
    win_patterns = [
        [0, 1, 2], [3, 4, 5], [6, 7, 8],
        [0, 3, 6], [1, 4, 7], [2, 5, 8],
        [0, 4, 8], [2, 4, 6]
    ]
    player = board[0]  # Assumes X always starts and fills first
    for pattern in win_patterns:
        if all(board[i] == player for i in pattern):
            return True, player
    return False, 0

def check_draw(board: np.ndarray) -> bool:
    """Checks if the game is a draw (all cells filled). Returns True if so."""
    return all(cell != EMPTY_CELL for cell in board)

